"use client"

import {
  ArrowDown01Icon,
  BlockGameIcon,
  BookOpen02Icon,
  BubbleChatIcon,
  Building02Icon,
  CallRinging04Icon,
  Chart03Icon,
  ChartColumnIcon,
  CodeIcon,
  DashboardBrowsingIcon,
  DashboardCircleIcon,
  Globe02Icon,
  GoogleDocIcon,
  Key01Icon,
  Message02Icon,
  PlayIcon,
  PlusSignIcon,
  Queue02Icon,
  RoboticIcon,
  Settings01Icon,
  ShieldKeyIcon,
  SmartPhone01Icon,
  CpuIcon,
  TaskDaily01Icon,
  TelephoneIcon,
  VariableIcon,
  VoiceIcon,
  WebhookIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/**
 * Icons for the shared product shell — one glyph per nav destination, matched
 * to the app's own sidebar. Icons *inside* a mockup live in that mockup's own
 * icons.tsx; this file is only the app chrome.
 */
export const PlaygroundIcon = icon(PlayIcon, "PlaygroundIcon")
export const PersonasIcon = icon(RoboticIcon, "PersonasIcon")
export const ScenariosIcon = icon(GoogleDocIcon, "ScenariosIcon")
export const KnowledgeIcon = icon(BookOpen02Icon, "KnowledgeIcon")
export const BatchCallsIcon = icon(Queue02Icon, "BatchCallsIcon")
export const TemplateIcon = icon(DashboardCircleIcon, "TemplateIcon")
export const GlobalPromptsIcon = icon(Globe02Icon, "GlobalPromptsIcon")
export const VoiceLibraryIcon = icon(VoiceIcon, "VoiceLibraryIcon")
export const DashboardIcon = icon(Chart03Icon, "DashboardIcon")
export const ConversationsIcon = icon(CallRinging04Icon, "ConversationsIcon")
export const MessagingIcon = icon(Message02Icon, "MessagingIcon")
export const QualityIcon = icon(DashboardBrowsingIcon, "QualityIcon")
export const ReportsIcon = icon(ChartColumnIcon, "ReportsIcon")
export const TasksIcon = icon(TaskDaily01Icon, "TasksIcon")
export const KeyIcon = icon(Key01Icon, "KeyIcon")
export const VariablesIcon = icon(VariableIcon, "VariablesIcon")
export const WebhooksIcon = icon(WebhookIcon, "WebhooksIcon")
export const IntegrationsIcon = icon(BlockGameIcon, "IntegrationsIcon")
export const DeveloperDocsIcon = icon(CodeIcon, "DeveloperDocsIcon")
export const BuildingIcon = icon(Building02Icon, "BuildingIcon")
export const RolesIcon = icon(ShieldKeyIcon, "RolesIcon")
export const MobileIcon = icon(SmartPhone01Icon, "MobileIcon")
/* The model catalog (DES-169), under Configuration. */
export const ModelsIcon = icon(CpuIcon, "ModelsIcon")
export const TelephonyIcon = icon(TelephoneIcon, "TelephonyIcon")
export const SettingsIcon = icon(Settings01Icon, "SettingsIcon")
export const MessagingSettingsIcon = icon(
  BubbleChatIcon,
  "MessagingSettingsIcon",
)
export const ChevronDownIcon = icon(ArrowDown01Icon, "ChevronDownIcon")
/** The hover "+" on Personas and Scenarios — creates one without leaving the nav. */
export const NewItemIcon = icon(PlusSignIcon, "NewItemIcon")

"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        <span className="truncate">{item.title}</span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
function AppHeader({
  breadcrumb,
  showSettings,
}: {
  breadcrumb: string
  showSettings: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>{breadcrumb}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        <Button size="sm" variant="outline">
          <DeveloperDocsIcon />
          Developer Doc
        </Button>
        {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
        {showSettings ? (
          <Button aria-label="Global settings" size="icon-sm" variant="outline">
            <SettingsIcon />
          </Button>
        ) : null}
        {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
        <div className="flex items-center">
          <Separator className="mx-1 h-4" orientation="vertical" />
        </div>
        {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
        <Avatar className="size-7 rounded-lg after:rounded-lg">
          <AvatarFallback className="rounded-lg">TA</AvatarFallback>
        </Avatar>
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Page label in the breadcrumb; defaults to `active`. */
  breadcrumb?: string
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    <SidebarProvider className="min-h-0 flex-1">
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="text-muted-foreground" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          breadcrumb={breadcrumb ?? active}
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="flex min-h-0 flex-1 flex-col overflow-auto">
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemMedia,
  ItemTitle,
} from "@/components/ui/item"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Textarea } from "@/components/ui/textarea"
import {
  AddIcon,
  CollectDigitsToolIcon,
  EndCallToolIcon,
  FindIcon,
  HttpRequestToolIcon,
  IvrToolIcon,
  RemoveIcon,
  SallaToolIcon,
  SwitchLanguageToolIcon,
  TransferToolIcon,
  VoicemailToolIcon,
  ZohoTicketToolIcon,
} from "@/components/scenario-single-screen/icons"
import { SheetSection } from "@/components/scenario-single-screen/setting-sheet"
import {
  type Destination,
  type ExtractionField,
  type KnowledgeBase,
  LANGUAGE_LABELS,
  type LanguageCode,
  type PerLanguage,
  PERSONAS,
  type SuccessCriterion,
  type TemplateVariable,
  type Tool,
  type ToolSlug,
} from "@/lib/scenario-single-screen-data"

const TIMEZONES = [
  "Asia/Riyadh",
  "Asia/Dubai",
  "Asia/Karachi",
  "Africa/Cairo",
  "Europe/London",
]

const TOOL_ICONS: Record<ToolSlug, React.ComponentType> = {
  "code-switching": SwitchLanguageToolIcon,
  "collect-digits": CollectDigitsToolIcon,
  "custom-api": HttpRequestToolIcon,
  "end-call": EndCallToolIcon,
  "ivr-navigation": IvrToolIcon,
  "salla-tools": SallaToolIcon,
  "transfer-to-human": TransferToolIcon,
  "voicemail-detection": VoicemailToolIcon,
  "zoho-desk-create-ticket": ZohoTicketToolIcon,
}

/* --------------------------------------------------------------- persona -- */

/**
 * A persona per language, because that is how the scenario stores it — one
 * voice cannot speak all three. Listing every configured language at once is
 * what stops this reading as a single "voice" dropdown that silently belongs
 * to whichever language you last had selected.
 */
export function PersonaDrawerBody({
  onPersonaChange,
  perLanguage,
}: {
  onPersonaChange: (language: LanguageCode, persona: string) => void
  perLanguage: PerLanguage[]
}) {
  return (
    <FieldGroup>
      {perLanguage.map((entry) => (
        <Field key={entry.language}>
          <FieldLabel htmlFor={`persona-${entry.language}`}>
            {LANGUAGE_LABELS[entry.language]}
          </FieldLabel>
          <Select
            onValueChange={(persona) => {
              onPersonaChange(entry.language, persona)
            }}
            value={entry.persona}
          >
            <SelectTrigger id={`persona-${entry.language}`}>
              <SelectValue placeholder="Select a persona" />
            </SelectTrigger>
            <SelectContent>
              {PERSONAS.map((persona) => (
                <SelectItem key={persona} value={persona}>
                  {persona}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <FieldDescription>
            Speaks the {LANGUAGE_LABELS[entry.language]} prompt and first
            message.
          </FieldDescription>
        </Field>
      ))}
    </FieldGroup>
  )
}

/* ------------------------------------------------------------- languages -- */

export function LanguagesDrawerBody({
  defaultLanguage,
  onDefaultChange,
  onTimezoneChange,
  perLanguage,
  timezone,
}: {
  defaultLanguage: LanguageCode
  onDefaultChange: (language: LanguageCode) => void
  onTimezoneChange: (timezone: string) => void
  perLanguage: PerLanguage[]
  timezone: string
}) {
  return (
    <>
      <SheetSection
        description="The default is the language a call opens in when the caller's is unknown."
        title="Configured languages"
      >
        <RadioGroup
          onValueChange={(value) => {
            onDefaultChange(value as LanguageCode)
          }}
          value={defaultLanguage}
        >
          <ItemGroup className="gap-2">
            {perLanguage.map((entry) => (
              <Item key={entry.language} size="sm" variant="outline">
                <ItemMedia>
                  <RadioGroupItem
                    id={`default-${entry.language}`}
                    value={entry.language}
                  />
                </ItemMedia>
                <ItemContent>
                  <ItemTitle>
                    <Label htmlFor={`default-${entry.language}`}>
                      {LANGUAGE_LABELS[entry.language]}
                    </Label>
                  </ItemTitle>
                </ItemContent>
                <ItemActions>
                  {entry.language === defaultLanguage ? (
                    <Badge variant="secondary">Default</Badge>
                  ) : (
                    <Button
                      aria-label={`Remove ${LANGUAGE_LABELS[entry.language]}`}
                      size="icon-sm"
                      variant="ghost"
                    >
                      <RemoveIcon />
                    </Button>
                  )}
                </ItemActions>
              </Item>
            ))}
          </ItemGroup>
        </RadioGroup>
        <Button size="sm" variant="outline">
          <AddIcon />
          Add a language
        </Button>
      </SheetSection>

      <SheetSection
        description="Dates and times the caller gives are read against this zone."
        title="Timezone"
      >
        <Select onValueChange={onTimezoneChange} value={timezone}>
          <SelectTrigger aria-label="Timezone">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {TIMEZONES.map((zone) => (
              <SelectItem key={zone} value={zone}>
                {zone}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </SheetSection>
    </>
  )
}

/* --------------------------------------------------------------- knowledge -- */

/**
 * Language coverage sits on every row, attached or not. A base with no content
 * in a language the scenario speaks is the failure this screen has to make
 * visible before it is attached, not after a call goes wrong.
 */
export function KnowledgeDrawerBody({
  bases,
  onToggle,
  spokenLanguages,
}: {
  bases: KnowledgeBase[]
  onToggle: (name: string) => void
  spokenLanguages: LanguageCode[]
}) {
  const [query, setQuery] = React.useState("")

  const matches = bases.filter((base) =>
    base.name.toLowerCase().includes(query.toLowerCase()),
  )

  return (
    <>
      <InputGroup>
        <InputGroupAddon>
          <FindIcon />
        </InputGroupAddon>
        <InputGroupInput
          aria-label="Search knowledge bases"
          onChange={(event) => {
            setQuery(event.target.value)
          }}
          placeholder="Search knowledge bases…"
          value={query}
        />
      </InputGroup>

      <ItemGroup className="gap-2">
        {matches.map((base) => {
          const gaps = spokenLanguages.filter(
            (language) => !base.languages.includes(language),
          )

          return (
            <Item key={base.name} size="sm" variant="outline">
              <ItemMedia>
                <Checkbox
                  checked={base.attached}
                  id={`kb-${base.name}`}
                  onCheckedChange={() => {
                    onToggle(base.name)
                  }}
                />
              </ItemMedia>
              <ItemContent>
                <ItemTitle>
                  <Label htmlFor={`kb-${base.name}`}>{base.name}</Label>
                </ItemTitle>
                <ItemDescription>
                  {base.documents} documents ·{" "}
                  {base.languages
                    .map((language) => LANGUAGE_LABELS[language])
                    .join(", ")}
                </ItemDescription>
              </ItemContent>
              {gaps.length > 0 && base.attached ? (
                <ItemActions>
                  <Badge variant="destructive">
                    No{" "}
                    {gaps
                      .map((language) => LANGUAGE_LABELS[language])
                      .join(", ")}
                  </Badge>
                </ItemActions>
              ) : null}
            </Item>
          )
        })}
      </ItemGroup>
    </>
  )
}

/* ------------------------------------------------------------------- tools -- */

/**
 * A tool's own configuration only appears once it is on. Nine tools each
 * showing their settings is the density that made the Configuration tab
 * unreadable; the switch is the disclosure.
 */
export function ToolsDrawerBody({
  onToggle,
  tools,
}: {
  onToggle: (slug: ToolSlug) => void
  tools: Tool[]
}) {
  return (
    <FieldGroup>
      {tools.map((tool) => {
        const Icon = TOOL_ICONS[tool.slug]

        return (
          <Field key={tool.slug} orientation="horizontal">
            <ItemMedia variant="icon">
              <Icon />
            </ItemMedia>
            <FieldContent>
              <FieldTitle>{tool.label}</FieldTitle>
              <FieldDescription>{tool.description}</FieldDescription>
              {tool.enabled && tool.summary ? (
                <div className="mt-2 flex items-center justify-between gap-3 rounded-lg bg-muted p-3">
                  <p className="text-sm text-muted-foreground">
                    {tool.summary}
                  </p>
                  <Button size="xs" variant="outline">
                    Edit
                  </Button>
                </div>
              ) : null}
            </FieldContent>
            <Switch
              aria-label={tool.label}
              checked={tool.enabled}
              onCheckedChange={() => {
                onToggle(tool.slug)
              }}
            />
          </Field>
        )
      })}
    </FieldGroup>
  )
}

/* -------------------------------------------------------- success criteria -- */

export function CriteriaDrawerBody({
  criteria,
  onCriteriaChange,
}: {
  criteria: SuccessCriterion[]
  onCriteriaChange: (criteria: SuccessCriterion[]) => void
}) {
  return (
    <>
      <FieldGroup>
        {criteria.map((criterion, index) => (
          <Field key={index}>
            <div className="flex items-center justify-between gap-2">
              <FieldLabel htmlFor={`criterion-${index}`}>
                Criterion {index + 1}
                {criterion.primary ? (
                  <Badge variant="secondary">Primary</Badge>
                ) : null}
              </FieldLabel>
              <Button
                aria-label={`Remove criterion ${index + 1}`}
                onClick={() => {
                  onCriteriaChange(criteria.filter((_, i) => i !== index))
                }}
                size="icon-sm"
                variant="ghost"
              >
                <RemoveIcon />
              </Button>
            </div>
            <Textarea
              id={`criterion-${index}`}
              onChange={(event) => {
                onCriteriaChange(
                  criteria.map((item, i) =>
                    i === index ? { ...item, text: event.target.value } : item,
                  ),
                )
              }}
              rows={3}
              value={criterion.text}
            />
          </Field>
        ))}
      </FieldGroup>

      <Button
        onClick={() => {
          onCriteriaChange([...criteria, { primary: false, text: "" }])
        }}
        size="sm"
        variant="outline"
      >
        <AddIcon />
        Add a criterion
      </Button>
    </>
  )
}

/* ------------------------------------------------------ template variables -- */

export function VariablesDrawerBody({
  onVariablesChange,
  variables,
}: {
  onVariablesChange: (variables: TemplateVariable[]) => void
  variables: TemplateVariable[]
}) {
  return (
    <>
      <div className="overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Variable</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Default</TableHead>
              <TableHead>Used in</TableHead>
              <TableHead className="text-end">Required</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {variables.map((variable, index) => (
              <TableRow key={variable.name}>
                <TableCell className="font-mono">{variable.name}</TableCell>
                <TableCell className="text-muted-foreground">
                  {variable.type}
                </TableCell>
                <TableCell>
                  <Input
                    aria-label={`Default value for ${variable.name}`}
                    onChange={(event) => {
                      onVariablesChange(
                        variables.map((item, i) =>
                          i === index
                            ? { ...item, defaultValue: event.target.value }
                            : item,
                        ),
                      )
                    }}
                    placeholder="—"
                    value={variable.defaultValue}
                  />
                </TableCell>
                <TableCell className="text-muted-foreground">
                  {variable.usedIn
                    .map((language) => language.toUpperCase())
                    .join(", ")}
                </TableCell>
                <TableCell className="text-end">
                  <Checkbox
                    aria-label={`${variable.name} is required`}
                    checked={variable.required}
                    onCheckedChange={() => {
                      onVariablesChange(
                        variables.map((item, i) =>
                          i === index
                            ? { ...item, required: !item.required }
