                        ),
                      )
                    }}
                  />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>

      <Button size="sm" variant="outline">
        <AddIcon />
        Add a variable
      </Button>
    </>
  )
}

